INSERT INTO objet_depart (id, nom, nom_cle, description, ordre, origine, source_ref, remarque) VALUES ('ressources/objets-de-depart-des-classes#objet:baton-magique-lvl1', 'Bâton magique lvl1', 'baton-magique-lvl1', 'Un bâton magique de votre magie innée vierge, vous pouvez y graver un sort niveau dedans. Attention, une fois que c''est fait, ce n''est plus changeable.', 4, 'classes', 'Classe Maverick V7 › Sommaire › A21:K92', NULL);
